    @org.junit.jupiter.api.io.TempDir Path directory;

    @Test
    void residentSummaryRecordsMissedColdReadyTargetWithoutAborting() throws Exception {
        var output = new ByteArrayOutputStream();
        PrintStream previous = System.out;
        try (var captured = new PrintStream(output, true, StandardCharsets.UTF_8)) {
            System.setOut(captured);
            assertThrows(Exception.class,
                    () -> Stage6Performance.runResident(directory.resolve("missing"), 8_001));
        } finally {
            System.setOut(previous);
        }
        assertTrue(output.toString(StandardCharsets.UTF_8).contains(
                "\"value\":8001,\"target\":8000,\"targetMet\":false,\"blocking\":false"));
    }

    @Test
    void resourceAndResidentLatencyLimitViolationsRemainFailures() {
        assertThrows(IllegalStateException.class, () -> Stage6Performance.metric("listP95Millis", 501, 500));
        assertThrows(IllegalStateException.class, () -> Stage6Performance.metric("hostRssBytes", 101, 100));
    }
}

